def bingo(array):
    alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    required_letters = set("BINGO")
    found_letters = set()

    for num in array:
        letter = alphabet[num - 1]
        if letter in required_letters:
